/***
*  ts_weapon_info.cpp — SHARED TS weapon data table (get_weapon_info).
*  Functional/source-faithful (see CLAUDE.md). Built into BOTH hl.so (server) and
*  client.so (client) so the predicted .sc event handlers read the same table.
*
*  The original builds a 38-entry table via compile_weapons_info() (@0x6fe28)
*  calling Write_<weapon>(&table[i]). We do the same with a clean s_weapon_info.
*  The table below is generated by scripts/extract_weapons.py straight from the
*  Write_<weapon> functions (name/models/anim-ext/fire/clip/damage/fire-type).
*  Index 29 (flag, a CTF objective) = the "Briefcase" entry (Write_flag, knife models as placeholder).
*
*  No engine deps — pure data, so it links on the client unchanged. The server-only
*  helpers (PrecacheAllTSWeapons/GiveTSWeapon/…) live in ts_weapons.cpp / ts_gun.cpp.
***/
#include "ts_weapon_info.h"
#include <string.h>
#include <math.h>

static s_weapon_info g_weaponInfo[TSW_COUNT];
static bool g_weaponInfoCompiled = false;

// ⚠ SPARTA TWO-STAGE: the dmg/spread/recoil (+ flViewKick set later from kWriteViewKick) that
// Write() stores here are the original's EARLIER INIT STAGE — Sparta() (called at the end of
// compile_weapons_info, mirroring the binary's Write_* -> Sparta order) OVERWRITES them for all
// 32 firearms. Only the 6 melee/grenade/flag rows keep their Write values for those four fields.
// Do NOT "fix" a combat-feel value here from a Write_ disasm read — fix it in Sparta().
static void Write(s_weapon_info *w, const char *name, const char *v, const char *p,
	const char *world, const char *anim, const char *fire, int clip, float dmg, int firetype,
	float rate, float spread, float recoil)
{
	w->pszName = name;
	w->pszViewModel = v;
	w->pszPlayerModel = p;
	w->pszWorldModel = world;
	w->pszAnimExt = anim ? anim : "onehanded";
	w->pszFireSound = fire;
	w->iClip = clip;
	w->flDamage = dmg;
	w->iFireType = firetype;
	w->flFireRate = rate;
	w->flSpread = spread;
	w->flRecoil = recoil;
	w->iAkimboType = -1; // default: no akimbo upgrade (set in compile_weapons_info)
	w->iSingleType = -1;
	w->iFireModes = 2;   // default: semi only (overridden in compile_weapons_info)
	w->iCaliber = 0;     // default: no caliber (overridden in compile_weapons_info)
	w->iPellets = 1;     // default: one bullet (overridden in compile_weapons_info)
	w->iFireAnim = -1;   // default: no standard fire anim (overridden in compile_weapons_info)
	w->iFireAnimL = -1;  // default: not akimbo (overridden in compile_weapons_info)
	w->iReloadAnim = -1; // default: no reload anim (overridden in compile_weapons_info)
	w->iHoldChange = -1; // default: no hold-position stance (overridden in compile_weapons_info)
	w->iHoldRechange = -1;
	w->iHoldFireAnim = -1;
	w->iHoldReloadAnim = -1; // default: reload uses iReloadAnim in both stances
	w->slotCost = 10;        // default inventory slot cost (overridden in compile_weapons_info)
	w->zoomFov1 = 0;         // default: no scope zoom (overridden in compile_weapons_info)
	w->zoomFov2 = 0;
	w->attachSupported = 0;  // default: mounts no attachments (overridden in compile_weapons_info)
	w->attachBuiltin = 0;    // default: ships with none
	w->iColdCockDamage = 0;  // default: can't coldcock (overridden per weapon below)
	w->iKnifeType = 0;       // default: not a throwable blade
	w->iIdleAnim = 0;        // shipped data: 0 for all rows (CCombatIdle table read)
	w->iSwingAnims[0] = w->iSwingAnims[1] = w->iSwingAnims[2] = 0; // blades override below
	w->iPrice = 0;           // set from the price table below
	w->iBodySilencer = w->iBodyLaser = w->iBodyFlash = w->iBodyScope = 0;
	w->iBodyLaserFlash = -1;
	w->flReloadTime = 0;         // +0x14 — set from the kReloadTime column below
	w->iStackable = 0;           // +0xdc — knife/sealknife/m61 override below
	w->iIdleAnimHold = -1;       // +0x28c hold block [0] — set from kHoldIdle below
	w->iReloadKeepAnim = -1;     // +0x262 block [8] — shell-retained reload (sawed-off)
	w->iReloadKeepAnimHold = -1; // +0x29c hold twin
	w->iColdCockAnim = -1;       // +0x28a block [28] — coldcock vm anim (set below)
	w->iColdCockAnimHold = -1;   // +0x2c4 hold twin
	for (int k = 0; k < 29; k++)
		w->animBlock[k] = w->animBlockHold[k] = -1; // the full blocks fill in compile_weapons_info
	w->pszAltSound = nullptr;   // +0x306 — set below (sil fire / pump rack / akimbo linked bang)
	w->pszShellModel = nullptr; // +0xe8 — set below
	w->iShellSetback = 0;       // +0x34c — set below
}

// SetSpartaWeapon (ts_i386.so @0x6fa34): the combat-param override applied after the Write_<weapon> stage.
// Overwrites the four fields the game actually uses for fire feel — flSpread/flViewKick/flRecoil/flDamage.
static void SetSpartaWeapon(int idx, float spread, float viewKick, float recoil, float dmg)
{
	g_weaponInfo[idx].flSpread = spread;   // +0x28
	g_weaponInfo[idx].flViewKick = viewKick; // +0x30
	g_weaponInfo[idx].flRecoil = recoil;   // +0x34
	g_weaponInfo[idx].flDamage = dmg;      // +0x1c
}

// ⚠⚠ SPARTA IS THE LIVE TRUTH for spread/viewkick/recoil/damage — and ONLY for those four.
// Anyone extracting weapon stats from the Write_<weapon> disasm must skip +0x1c/+0x28/+0x30/
// +0x34 (dead stage) and must NOT expect Sparta to carry anything else (clips/caps/prices/anim
// blocks are Write_-stage). The pair below is BYTE-IDENTICAL to the client's copy
// (FUN_10007a80 -> FUN_10007a50), so server sim and client prediction/recoil agree.
// === Sparta() — the authoritative combat-param OVERRIDE. RE: ts_i386.so Sparta() @0x6fa78 ->
// SetSpartaWeapon(idx, spread, viewKick, recoil, dmg) @0x6fa34, BYTE-IDENTICAL to client.dll
// FUN_10007a80 -> FUN_10007a50. It runs after every Write_<weapon> and OVERWRITES the four combat fields:
// flSpread(+0x28), flViewKick(+0x30), flRecoil(+0x34), flDamage(+0x1c). The Write_<weapon> values are an
// earlier init stage — THESE are what the game actually uses (server damage/spread sim AND client recoil/
// prediction both run Sparta). Only the 32 firearms are listed; the 6 melee/grenade/flag indices keep
// their Write_ values. ~22 differed from Write (skorpion vk 0.25->0.5 [live-verified], bull 18->13,
// mossberg 14->8.5, benelli 10->13, beretta dmg/vk, barrett dmg 185, ...). Calls in the original order.
